package local.lito381.server;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Original HP Commit construction and final encrypted IO; no actual clock/HP/server/SQL. */
public final class SourceElementAudiencePlan {
 static int cases,ctors,frames,waits,discoveryWaits;static void check(boolean b,String s){if(!b)throw new AssertionError(s);cases++;}static void set(Object o,String k,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,k,v);}static Object state(ClientSession pc){return SourceElementTransportPlan.state(pc);}
 static Object commit(SourceElementTransportPlan.Fixture f,boolean cube)throws Exception{Object p;synchronized(f.base().base().hub()){synchronized(f.base().encounter()){if(cube){var c=new NativeSourceCubeNpc.Commit(f.cube().lease,f.base().base().life(),true);c.seal(SourcePhysicalAudiencePlan.record(f.lease().quest?BattleQuestEncounter.Hit.class:GameHub.TimeAttackActorHit.class));p=c;}else{var c=new NativeSourcePoisonNpc.Commit(f.lease(),f.poison().origin,7);c.seal(SourcePhysicalAudiencePlan.record(f.lease().quest?BattleQuestEncounter.Hit.class:GameHub.TimeAttackActorHit.class));p=c;}}}ctors++;return p;}
 @SuppressWarnings("unchecked")static List<ClientSession> members(Object p){return (List<ClientSession>)CombatAccess.field(p,"members");}
 @SuppressWarnings("unchecked")static Map<ClientSession,NativePlayerCommit.Binding> bindings(Object p){return (Map<ClientSession,NativePlayerCommit.Binding>)CombatAccess.field(p,"viewers");}
 static boolean current(Object p,ClientSession pc){return p instanceof NativeSourceCubeNpc.Commit c?NativeSourceCubeNpc.receiver(c,pc,c.viewers.get(pc)):NativeSourcePoisonNpc.receiver((NativeSourcePoisonNpc.Commit)p,pc,bindings(p).get(pc));}
 static void send(Object p,ClientSession pc,byte[] packet){if(p instanceof NativeSourceCubeNpc.Commit c)NativeSourceCubeNpc.output(c,pc,c.viewers.get(pc),packet,"detached cube first audience",false);else{var c=(NativeSourcePoisonNpc.Commit)p;NativeSourcePoisonNpc.output(c,pc,c.viewers.get(pc),packet,"detached poison first audience",false);}}
 static void replaceStatus(ClientSession pc,Object status){try{set(pc,"timedStatus",status);}catch(Exception e){throw new AssertionError(e);}}
 static void blocked(Thread worker,String what)throws Exception{long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(worker.isAlive()&&worker.getState()!=Thread.State.BLOCKED&&System.nanoTime()<until)Thread.yield();check(worker.getState()==Thread.State.BLOCKED,what);}
 static void waitReject(Object p,ClientSession pc,byte[] packet,Runnable mutation,String what)throws Exception{var socket=SourceNpcHpOutputPlan.io(pc);long cipher=((Protocol.CipherState)CombatAccess.field(pc,"outgoing")).value();var began=new CountDownLatch(1);var failure=new AtomicReference<Throwable>();var restored=new AtomicBoolean();var sentinel=SourceFirstPlayersPlan.context();var worker=new Thread(()->{try{NativeAreaMaterialAction.current.set(sentinel);began.countDown();send(p,pc,packet);restored.set(NativeAreaMaterialAction.current.get()==sentinel);}catch(Throwable e){failure.set(e);}finally{NativeAreaMaterialAction.current.remove();}},"element-first-audience-final-wait");synchronized(pc){worker.start();check(began.await(3,TimeUnit.SECONDS),"final worker started");blocked(worker,"original final receiver monitor waits "+what);mutation.run();}worker.join(3000);check(!worker.isAlive()&&failure.get()==null&&restored.get()&&socket.bytes.size()==0&&((Protocol.CipherState)CombatAccess.field(pc,"outgoing")).value()==cipher,"first proof fences before cipher and restores TLS "+what);waits++;}
 static void firstWait(SourceElementTransportPlan.Fixture f,boolean cube)throws Exception{var b=f.base().base();var began=new CountDownLatch(1);var result=new AtomicReference<Object>();var failure=new AtomicReference<Throwable>();var worker=new Thread(()->{try{began.countDown();result.set(commit(f,cube));}catch(Throwable e){failure.set(e);}},"element-first-discovery-before-original-bindings");synchronized(CombatPoisonAtomic.status(b.observer())){worker.start();check(began.await(3,TimeUnit.SECONDS),"first discovery worker started");blocked(worker,"constructor waits at fourth original receiver status domain after first viewer capture");NativePlayerCommit.scene(b.viewer(),2L,"currentRoomId");NativePlayerCommit.scene(b.viewer(),1L,"currentRoomId");}worker.join(3000);check(!worker.isAlive()&&failure.get()==null&&result.get()!=null,"original constructor finishes after discovery wait");var p=result.get();check(NativeAcceptedFreezeMutation.roleFrame(bindings(p).get(b.viewer()),b.viewer())&&!current(p,b.viewer()),"later original binding cannot adopt a role after first-discovery scene ABA");check(current(p,b.observer()),"unmodified first observer remains valid after another viewer retirement");discoveryWaits++;}
 static void run(boolean timed,boolean cube)throws Exception{var f=SourceElementTransportPlan.fixture(timed);var b=f.base().base();Object life=NativeSourceControlledDisplay.rawLife(b.observer());CombatAccess.set(state(b.observer()),"sourceNpcOwner",null);CombatAccess.set(state(b.viewer()),"sourceNpcOwner",null);var p=commit(f,cube);var list=members(p);check(list instanceof NativeSourceElementAudience.Audience&&list.equals(List.of(b.caster(),b.target(),b.viewer(),b.observer())),"original complete constructor preserves ordered audience");var first=(NativeSourceElementAudience.Audience)list;check(first.first.size()==4&&first.first.get(b.observer()).life()==null&&first.first.get(b.observer()).observer()&&NativeSourceControlledDisplay.rawLife(b.observer())==null,"nullable-life first observer creates no actor token");check(first.first.get(b.viewer()).life()!=null&&first.first.get(b.viewer()).life()==NativeSourceControlledDisplay.rawLife(b.viewer()),"living receiver canonical life is initialized only at original first discovery");try{first.first.clear();throw new AssertionError("immutable first map");}catch(UnsupportedOperationException expected){check(true,"first receiver map immutable");}try{list.clear();throw new AssertionError("immutable audience");}catch(UnsupportedOperationException expected){check(true,"original audience list remains immutable");}
  byte[] packet=Protocol.effectObject(f.base().aim().npc().id(),44);for(var pc:List.of(b.viewer(),b.observer())){check(current(p,pc),"first living/dead observer valid");var socket=SourceNpcHpOutputPlan.io(pc);send(p,pc,packet);check(socket.bytes.size()==packet.length+2,"complete original HP output and final cipher emits original first audience");frames++;}
  Object viewerLife=NativeSourceControlledDisplay.rawLife(b.viewer());waitReject(p,b.viewer(),packet,()->CombatAccess.set(state(b.viewer()),"sourceNpcOwner",new Object()),"living viewer revival");CombatAccess.set(state(b.viewer()),"sourceNpcOwner",viewerLife);
  waitReject(p,b.observer(),packet,()->CombatAccess.set(b.observer(),"observer",false),"observer becomes living");CombatAccess.set(b.observer(),"observer",true);
  waitReject(p,b.observer(),packet,()->CombatAccess.set(state(b.observer()),"sourceNpcOwner",new Object()),"nullable observer receives later life");CombatAccess.set(state(b.observer()),"sourceNpcOwner",null);
  var status=CombatAccess.field(b.viewer(),"timedStatus");var other=new BattleTimedStatus();set(other,"sourcePoisonLifecycle",CombatAccess.field(status,"sourcePoisonLifecycle"));waitReject(p,b.viewer(),packet,()->replaceStatus(b.viewer(),other),"same owner/life in replaced status container");set(b.viewer(),"timedStatus",status);
  waitReject(p,b.viewer(),packet,()->{NativePlayerCommit.scene(b.viewer(),2L,"currentRoomId");NativePlayerCommit.scene(b.viewer(),1L,"currentRoomId");},"actual scene ABA");check(!current(p,b.viewer())&&current(p,b.observer()),"retired role invalidates only its original first receiver");
  set(b.life(),"mode",NativePlayerLifetime.Mode.DRAINING);check(current(p,b.observer()),"accepted DRAINING first observer retained");set(b.life(),"mode",NativePlayerLifetime.Mode.STOPPED);check(!current(p,b.observer()),"original STOPPED gate retained");set(b.life(),"mode",NativePlayerLifetime.Mode.OPEN);set(b.hub(),"nativeStaticMotionClosed",true);check(!current(p,b.observer()),"original Main close gate retained");set(b.hub(),"nativeStaticMotionClosed",false);
  var unknown=SourceSignedRecoveryPlan.shell(b.hub(),"absent-first-viewer");check(!NativeSourceElementAudience.current(list,list,unknown,NativePlayerCommit.Binding.capture(unknown)),"published missing receiver never rediscovered");check(NativeSourceElementAudience.current(List.of(),List.of(),unknown,null),"unmarked original list fallback remains");
  CombatAccess.set(state(b.observer()),"sourceNpcOwner",life);firstWait(f,cube);
 }
 public static void main(String[]args)throws Exception{var area=NativeAreaMaterialAction.current;var oldArea=area.get();var framesLocal=SourceNpcHpOutputPlan.frames();var oldFrame=framesLocal.get();var batches=SourceNpcHpOutputPlan.batches();var oldBatch=batches.get();var rules=CombatRules.class.getDeclaredField("current");rules.setAccessible(true);var oldRules=rules.get(null);var controls=NativeSourceOtherControls.class.getDeclaredField("current");controls.setAccessible(true);var oldControls=controls.get(null);try{area.remove();framesLocal.remove();batches.remove();var path=java.nio.file.Path.of("detached-element-first-audience-no-Source-reader");rules.set(null,new CombatRules.Snapshot(Map.of(),path,path,path,Set.of(),path));var props=new Properties();props.setProperty("hpbar","true");controls.set(null,new NativeSourceOtherControls.Snapshot(NativeSourceDisplayPlan.Settings.read(props),path));for(boolean timed:List.of(false,true))for(boolean cube:List.of(false,true))run(timed,cube);check(NativeSourceElementAudience.class.getDeclaredFields().length==0,"no new global roots/TLS/registry/queue");for(var field:NativeSourceElementAudience.Receiver.class.getDeclaredFields())check(!Set.of(ClientSession.class,NativeAreaMaterialAction.Context.class,NativePlayerCommit.Frame.class,BattleTimedStatus.class).contains(field.getType()),"receiver proof has no strong pc/Context/Frame/status field");check(ctors==8&&frames==8&&waits==20&&discoveryWaits==4,"two natural kinds and both HP producers exercise original construction/cipher/discovery waits");}finally{if(oldArea==null)area.remove();else area.set(oldArea);if(oldFrame==null)framesLocal.remove();else framesLocal.set(oldFrame);if(oldBatch==null)batches.remove();else batches.set(oldBatch);rules.set(null,oldRules);controls.set(null,oldControls);}check(area.get()==oldArea&&framesLocal.get()==oldFrame&&batches.get()==oldBatch&&rules.get(null)==oldRules,"all original rules/controls/TLS restored");System.out.println("PASS"+cases+" element first-audience original-ctor/final-cipher contracts; original-ctors="+ctors+", memory-frames="+frames+", final-receiver-waits="+waits+", first-discovery-waits="+discoveryWaits+"; status-first-viewer/whole-submit/HP/backend/Main/memory/Source/game/MySQL remain open");}
}
